public class Main {
    public static void main(String[] args) throws Exception {
        FastReader r = new FastReader();
        int n = r.nextInt();
        long[] a = new long[n], b = new long[n];
        for (int i = 0; i < n; i++) a[i] = r.nextLong();
        for (int i = 0; i < n; i++) b[i] = r.nextLong();
        Arrays.sort(a);
        Arrays.sort(b);
